abstract class Builder<T extends Builder<T>> {
    private String name;
    protected abstract T self();               // returns the concrete builder
    public T named(String value) { name = value; return self(); }
}

final class UserBuilder extends Builder<UserBuilder> {
    @Override protected UserBuilder self() { return this; }
    public UserBuilder withEmail(String email) { return this; }
}
